type BookingFlowProps = {
  slug: string;
  stylist: PublicStylist;
  initialReferralCode?: string | null;
  initialServiceIds?: string[];
  initialSuggestedDates?: string[];
  initialBookingInquiryToken?: string | null;
};

type BookingIntakeState =
  | { status: "idle" }
  | { status: "loading" }
  | { status: "ready"; data: PublicBookingIntakeData }
  | { status: "error"; message: string };

type BookingInquiryHandoffState =
  | { status: "idle" }
  | { status: "loading" }
  | { status: "ready"; data: BookingInquiryHandoff }
  | { status: "fallback"; message?: string };

type AvailabilityDayPreview = {
  date: string;
  slots: PublicSlot[];
};

function filterRejectedSlots(slots: PublicSlot[], rejectedStarts: string[]) {
  if (!rejectedStarts.length) {
    return slots;
  }

  const rejectedStartSet = new Set(rejectedStarts);
  return slots.filter((slot) => !rejectedStartSet.has(slot.start));
}

function getBookableSlots(response: PublicSlotsResponse) {
  const slotMap = new Map<string, PublicSlot>();

  [...(response.slots ?? []), ...(response.moreSlots ?? [])].forEach((slot) => {
    slotMap.set(slot.start, slot);
  });

  return Array.from(slotMap.values());
}

function normalizeReferralCode(value?: string | null) {
  return value?.trim() || null;
}

export function getUsableBookingAttributionToken(
  attribution: StoredAttribution | null,
  stylistSlug: string,
) {
  const expiresAt = attribution ? Date.parse(attribution.expiresAt) : Number.NaN;

  if (
    !attribution?.token.trim()
    || attribution.stylistSlug !== stylistSlug
    || !Number.isFinite(expiresAt)
    || expiresAt <= Date.now()
  ) {
    return undefined;
  }

  return attribution.token;
}

export function getBookingAttributionErrorCode(error: unknown) {
  if (!(error instanceof ApiError)) {
    return null;
  }

  switch (error.code) {
    case "booking_attribution_context_stylist_mismatch":
    case "booking_attribution_context_unavailable":
      return error.code;
    default:
      return null;
  }
}

function normalizePrefillValues(values?: string[]) {
  return Array.from(new Set((values ?? []).map((value) => value.trim()).filter(Boolean)));
}

function getReferralStorageKey(slug: string) {
  return `referral:${slug}`;
}

function getSlotCacheKey({
  bookingContextToken,
  date,
  serviceIds,
}: {
  bookingContextToken: string;
  date: string;
  serviceIds: string[];
}) {
  return [bookingContextToken, date, [...serviceIds].sort().join("|")].join("::");
}

function createBookingIdempotencyKey() {
  if (typeof crypto !== "undefined" && "randomUUID" in crypto) {
    return crypto.randomUUID();
  }

  return `${Date.now()}-${Math.random().toString(36).slice(2)}`;
}

function readStoredReferralCode(slug: string) {
  if (typeof sessionStorage === "undefined") {
    return null;
  }

  try {
    return normalizeReferralCode(
      sessionStorage.getItem(getReferralStorageKey(slug)),
    );
  } catch {
    return null;
  }
}

function clearStoredReferralCode(slug: string) {
  if (typeof sessionStorage === "undefined") {
    return;
  }

  try {
    sessionStorage.removeItem(getReferralStorageKey(slug));
  } catch {
    // Referral cleanup should never block a completed booking.
  }
}

function removeBookingInquiryTokenFromUrl() {
  const url = new URL(window.location.href);

  if (!url.searchParams.has("booking_inquiry_token")) {
    return;
  }

  url.searchParams.delete("booking_inquiry_token");
  window.history.replaceState(window.history.state, "", `${url.pathname}${url.search}${url.hash}`);
}

function toHandoffService(handoff: BookingInquiryHandoff): PublicService {
  return {
    id: handoff.service.id,
    name: handoff.service.name,
    durationMinutes: handoff.service.duration_minutes,
    price: handoff.service.price,
    isActive: true,
    isDefault: false,
    sortOrder: 0,
  };
}

function toHandoffIntake(handoff: BookingInquiryHandoff): PublicBookingIntakeData {
  return {
    matchStatus: "matched",
    clientFound: true,
    isExistingClient: true,
    bookingContextToken: handoff.booking_context_token,
    bookingEnabled: true,
    client: null,
    submittedContact: {
      fullName: "",
      firstName: "",
      lastName: "",
      phoneNormalized: "",
      email: null,
    },
    recommendedService: null,
    bookingBehavior: {
      requiresApproval: false,
      restrictedToNewClientRules: false,
      canUseReturningClientRules: true,
      message: "",
    },
  };
}

export function BookingFlow({
  slug,
  stylist,
  initialReferralCode,
  initialServiceIds,
  initialSuggestedDates,
  initialBookingInquiryToken,
}: BookingFlowProps) {
  const bookingAttribution = useBookingAttribution();
  const clearBookingAttribution = useClearBookingAttribution();
  const [referralCode, setReferralCode] = useState<string | null>(() =>
    normalizeReferralCode(initialReferralCode) ?? readStoredReferralCode(slug),
  );
  const bookingInquiryToken = initialBookingInquiryToken ?? null;
  const [handoffState, setHandoffState] = useState<BookingInquiryHandoffState>(
    bookingInquiryToken ? { status: "loading" } : { status: "idle" },
  );
  const [currentStep, setCurrentStep] = useState(1);
  const [notes, setNotes] = useState("");
  const [smsOptIn, setSmsOptIn] = useState(false);
  const [intakeState, setIntakeState] = useState<BookingIntakeState>({
    status: "idle",
  });
  const [bookingDisabledByFlow, setBookingDisabledByFlow] = useState(false);
  const [intakeRefreshing, setIntakeRefreshing] = useState(false);
  const [services, setServices] = useState<PublicService[]>([]);
  const [servicesLoading, setServicesLoading] = useState(false);
  const [servicesLoadedToken, setServicesLoadedToken] = useState<string | null>(
    null,
  );
  const [serviceError, setServiceError] = useState<string | null>(null);
  const [selectedServices, setSelectedServices] = useState<PublicService[]>([]);
  const [dateOptions, setDateOptions] = useState<string[]>([]);
  const [selectedDate, setSelectedDate] = useState<string>("");
  const [slots, setSlots] = useState<PublicSlot[]>([]);
  const [loadedSlotsDate, setLoadedSlotsDate] = useState<string>("");
  const [slotPreviews, setSlotPreviews] = useState<
    Record<string, PublicSlot[]>
  >({});
  const [selectedSlot, setSelectedSlot] = useState<PublicSlot | null>(null);
  const [rejectedSlotStarts, setRejectedSlotStarts] = useState<string[]>([]);
  const [availabilityLoading, setAvailabilityLoading] = useState(false);
  const [slotsError, setSlotsError] = useState<string | null>(null);
  const [availabilityTimezone, setAvailabilityTimezone] = useState<
    string | null
  >(stylist.timezone ?? null);
  const [confirmError, setConfirmError] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);
  const [confirmation, setConfirmation] =
    useState<PublicBookingConfirmation | null>(null);
  const [referencePhotoFile, setReferencePhotoFile] = useState<File | null>(
    null,
  );
  const [referencePhotoPreviewUrl, setReferencePhotoPreviewUrl] = useState<
    string | null
  >(null);

  // Intake is the gatekeeper for booking rules: it tells the UI whether booking
  // is allowed and provides a short-lived context token for services/slots.
  const intakeData = intakeState.status === "ready" ? intakeState.data : null;
  const activeHandoff = handoffState.status === "ready" ? handoffState.data : null;
  const isDirectHandoff = activeHandoff?.next_step === "select_datetime";
  const bookingContextToken = intakeData?.bookingContextToken ?? null;
  const bookingDisabled =
    !stylist.booking_enabled ||
    bookingDisabledByFlow ||
    intakeData?.bookingEnabled === false;
  const canShowWaitlist =
    stylist.booking_enabled === true &&
    stylist.features?.waitlistEnabled === true;
  const servicesAreSynced =
    Boolean(bookingContextToken) && servicesLoadedToken === bookingContextToken;
  const sortedServices = useMemo(() => sortServices(services), [services]);
  const activeTimezone = availabilityTimezone || stylist.timezone || null;
  const pageName = buildSummaryName(stylist);
  const selectedServiceIds = useMemo(
    () => selectedServices.map((service) => service.id),
    [selectedServices],
  );
  const primarySelectedService = selectedServices[0] ?? null;
  const canShowTimeStep = Boolean(selectedServices.length && selectedDate);
  const availabilityLoaded =
    Boolean(selectedDate) && loadedSlotsDate === selectedDate;
  const shouldShowWaitlistCta =
    // Waitlist is intentionally feature-gated by public stylist metadata and
    // only appears after an actual empty-slot result for the selected date.
    !isDirectHandoff &&
    canShowWaitlist &&
    selectedServiceIds.length > 0 &&
    Boolean(selectedDate) &&
    availabilityLoaded &&
    !availabilityLoading &&
    !slotsError &&
    slots.length === 0;
  const upcomingAvailabilityDays = useMemo<AvailabilityDayPreview[]>(() => {
    const today = getTodayDateValue();
    const orderedDates = Array.from(
      new Set([...dateOptions, selectedDate].filter(Boolean)),
    ).filter((date) => date >= today);

    return orderedDates
      .map((date) => ({
        date,
        slots: filterRejectedSlots(
          slotPreviews[date] ??
            (date === selectedDate &&
            loadedSlotsDate === selectedDate &&
            slots.length
              ? slots
              : []),
          rejectedSlotStarts,
        ),
      }))
      .filter((day) => day.slots.length > 0);
  }, [
    dateOptions,
    loadedSlotsDate,
    rejectedSlotStarts,
    selectedDate,
    slotPreviews,
    slots,
  ]);

  const selectedServicesRef = useRef(selectedServices);
  const referralCodeRef = useRef(referralCode);
  const initialServiceIdsRef = useRef(normalizePrefillValues(initialServiceIds));
  const initialSuggestedDatesRef = useRef(
    normalizePrefillValues(initialSuggestedDates),
  );
  const initialServicePrefillAttemptedRef = useRef(false);
  const handoffResolutionPromiseRef = useRef<Promise<BookingInquiryHandoff> | null>(null);
  const submittingRef = useRef(false);
  // Token refreshes can be triggered by several concurrent availability calls;
  // share one in-flight refresh to avoid duplicate intake requests.
  const tokenRefreshPromiseRef = useRef<Promise<PublicBookingIntakeData | null> | null>(
    null,
  );
  const slotResponseCacheRef = useRef<Map<string, PublicSlotsResponse>>(new Map());
  const slotRequestCacheRef = useRef<
    Map<string, Promise<PublicSlotsResponse | null>>
  >(new Map());

  useEffect(() => {
    referralCodeRef.current = referralCode;
  }, [referralCode]);

  useEffect(() => {
    const storageKey = getReferralStorageKey(slug);
    const nextReferralCode = normalizeReferralCode(initialReferralCode);
    let timeoutId: number | null = null;

    function scheduleReferralCodeUpdate(value: string | null) {
      timeoutId = window.setTimeout(() => {
        setReferralCode(value);
      }, 0);
    }

    if (nextReferralCode) {
      scheduleReferralCodeUpdate(nextReferralCode);

      try {
        sessionStorage.setItem(storageKey, nextReferralCode);
      } catch {
        // Referral attribution should never block booking if storage is unavailable.
      }

      return () => {
        if (timeoutId !== null) {
          window.clearTimeout(timeoutId);
        }
      };
    }

    scheduleReferralCodeUpdate(readStoredReferralCode(slug));

    return () => {
      if (timeoutId !== null) {
        window.clearTimeout(timeoutId);
      }
    };
  }, [initialReferralCode, slug]);

  useEffect(() => {
    selectedServicesRef.current = selectedServices;
  }, [selectedServices]);

  useEffect(() => {
    return () => {
      if (referencePhotoPreviewUrl) {
        URL.revokeObjectURL(referencePhotoPreviewUrl);
      }
    };
  }, [referencePhotoPreviewUrl]);

  const clearAvailabilityState = useCallback(() => {
    // Service/contact changes invalidate every date and slot derived from the
    // previous booking context token.
    slotResponseCacheRef.current.clear();
    slotRequestCacheRef.current.clear();
    setDateOptions([]);
    setSelectedDate("");
    setSlots([]);
    setLoadedSlotsDate("");
    setSlotPreviews({});
    setSelectedSlot(null);
    setRejectedSlotStarts([]);
    setSlotsError(null);
    setAvailabilityTimezone(stylist.timezone ?? null);
  }, [stylist.timezone]);

  const disableBookingFlow = useCallback(() => {
    setBookingDisabledByFlow(true);
    setServices([]);
    setServicesLoadedToken(null);
    setSelectedServices([]);
    clearAvailabilityState();
    setCurrentStep(1);
    setServiceError(null);
    setConfirmError(null);
  }, [clearAvailabilityState]);

  const invalidateBookingContext = useCallback(() => {
    setIntakeState({ status: "idle" });
    setServices([]);
    setServicesLoadedToken(null);
    setSelectedServices([]);
    clearAvailabilityState();
    setCurrentStep(1);
    setServiceError(null);
    setConfirmError(null);
  }, [clearAvailabilityState]);

  const discardDirectHandoff = useCallback((
    message?: string,
    { clearPrefills = true }: { clearPrefills?: boolean } = {},
  ) => {
    setHandoffState({ status: "fallback", ...(message ? { message } : {}) });
    setIntakeState({ status: "idle" });
    setServices([]);
    setServicesLoadedToken(null);
    setSelectedServices([]);
    if (clearPrefills) {
      initialServiceIdsRef.current = [];
      initialSuggestedDatesRef.current = [];
      initialServicePrefillAttemptedRef.current = true;
    }
    clearAvailabilityState();
    setCurrentStep(1);
    setServiceError(message ?? null);
    setConfirmError(null);
  }, [clearAvailabilityState]);

  useEffect(() => {
    if (!bookingInquiryToken) {
      return;
    }

    removeBookingInquiryTokenFromUrl();
    const resolution = handoffResolutionPromiseRef.current
      ?? resolveBookingInquiryHandoff(bookingInquiryToken);
    handoffResolutionPromiseRef.current = resolution;
    let active = true;

    void resolution
      .then((handoff) => {
        if (!active) return;

        if (handoff.next_step !== "select_datetime") {
          discardDirectHandoff(undefined, { clearPrefills: false });
          return;
        }

        const service = toHandoffService(handoff);
        clearAvailabilityState();
        initialServiceIdsRef.current = [service.id];
        initialSuggestedDatesRef.current = handoff.suggested_dates;
        initialServicePrefillAttemptedRef.current = true;
        setHandoffState({ status: "ready", data: handoff });
        setIntakeState({ status: "ready", data: toHandoffIntake(handoff) });
        setServices([service]);
        setServicesLoadedToken(handoff.booking_context_token);
        setSelectedServices([service]);
        setServiceError(null);
        setCurrentStep(3);
      })
      .catch(() => {
        if (active) {
          discardDirectHandoff(
            "We couldn't use that recommendation link. Please continue with your contact details.",
            { clearPrefills: false },
          );
        }
      });

    return () => {
      active = false;
    };
  }, [bookingInquiryToken, clearAvailabilityState, discardDirectHandoff]);

  const {
    contactValues,
    contactValuesRef,
    detailsErrors,
    email,
    fullName,
    handleDetailsChange,
    parsedName,
    phone,
    resetDetails,
    validateDetails,
  } = useBookingDetails({
    onDetailsChanged: () => {
      if (intakeState.status !== "idle" || services.length || servicesLoadedToken) {
        invalidateBookingContext();
      }
    },
  });

  const canBeginServiceSelection =
    Boolean(contactValues.fullName.trim()) && Boolean(contactValues.phone.trim());

  const handleBookingContextRecoveryFailure = useCallback(
    (message: string) => {
      clearAvailabilityState();
      setCurrentStep(1);
      setServiceError(message);
      setConfirmError(null);
    },
    [clearAvailabilityState],
  );

  const runIntake = useCallback(
    async ({ background = false }: { background?: boolean } = {}) => {
      const currentValues = contactValuesRef.current;

      // Avoid calling intake until client-side validation says the backend has
      // enough data to match returning-client booking rules.
      if (!detailsAreValid(currentValues)) {
        return null;
      }

      if (background) {
        setIntakeRefreshing(true);
      } else {
        setIntakeState({ status: "loading" });
        setServiceError(null);
      }

      try {
        const intake = await createPublicBookingIntake({
          stylist_slug: slug,
          full_name: currentValues.fullName.trim(),
          phone: currentValues.phone.trim(),
          email: currentValues.email.trim(),
        });

        setIntakeState({ status: "ready", data: intake });

        if (!intake.bookingEnabled) {
          disableBookingFlow();
        }

        return intake;
      } catch (error) {
        const message =
          error instanceof Error
            ? error.message
            : "We couldn't check your booking details right now.";

        setIntakeState({ status: "error", message });
        if (!background) {
          setServiceError(message);
        }
        return null;
      } finally {
        if (background) {
          setIntakeRefreshing(false);
        }
      }
    },
    [contactValuesRef, disableBookingFlow, slug],
  );

  const refreshBookingContext = useCallback(async () => {
    if (tokenRefreshPromiseRef.current) {
      return tokenRefreshPromiseRef.current;
    }

    const refreshPromise = (async () => {
      const refreshedIntake = await runIntake({ background: true });

      if (!refreshedIntake) {
        return null;
      }

      return refreshedIntake;
    })();

    tokenRefreshPromiseRef.current = refreshPromise.finally(() => {
      tokenRefreshPromiseRef.current = null;
    });

    return tokenRefreshPromiseRef.current;
  }, [runIntake]);

  const loadServicesForIntake = useCallback(
    async (
      intake: PublicBookingIntakeData,
      { allowTokenRefresh = true }: { allowTokenRefresh?: boolean } = {},
    ) => {
      setServicesLoading(true);
      setServiceError(null);

      const applyServices = (
        nextServices: PublicService[],
        nextIntake: PublicBookingIntakeData,
      ) => {
        // Keep any still-valid user selections after a context refresh, and
        // auto-select the backend recommendation only when nothing is selected.
        setServices(nextServices);
        setServicesLoadedToken(nextIntake.bookingContextToken);

        const currentSelectedServices = selectedServicesRef.current;
        const nextSelectedServices = currentSelectedServices.filter((service) =>
          nextServices.some(
            (availableService) => availableService.id === service.id,
          ),
        );
        const initialServiceId =
          !initialServicePrefillAttemptedRef.current &&
          initialServiceIdsRef.current.length === 1
            ? initialServiceIdsRef.current[0]
            : null;
        const prefilledService = initialServiceId
          ? nextServices.find((service) => service.id === initialServiceId) ?? null
          : null;
        initialServicePrefillAttemptedRef.current = true;
        const recommendedService =
          nextSelectedServices.length === 0 &&
          !prefilledService &&
          nextIntake.recommendedService?.serviceId
            ? nextServices.find(
                (service) =>
                  service.id === nextIntake.recommendedService?.serviceId,
              ) ?? null
            : null;
        const resolvedSelectedServices = prefilledService
          ? [prefilledService]
          : recommendedService
            ? [recommendedService]
            : nextSelectedServices;
        const selectionChanged =
          currentSelectedServices.length !== resolvedSelectedServices.length ||
          currentSelectedServices.some(
            (service, index) => resolvedSelectedServices[index]?.id !== service.id,
          );

        setSelectedServices(resolvedSelectedServices);

        if (initialServiceId && !prefilledService) {
          setServiceError(
            "The suggested service is no longer available. Please choose another service.",
          );
        }

        if (selectionChanged) {
          clearAvailabilityState();

          if (currentSelectedServices.length > 0) {
            setCurrentStep(2);
            setServiceError("Your available services changed. Please choose again.");
          }
        }
      };

      try {
        const nextServices = await getPublicServices(
          slug,
          intake.bookingContextToken,
        );
        applyServices(nextServices, intake);
        return nextServices;
      } catch (error) {
        if (isBookingDisabledError(error)) {
          setServices([]);
          setServicesLoadedToken(null);
          disableBookingFlow();
          return null;
        }

        if (allowTokenRefresh && isBookingContextExpiredError(error)) {
          if (isDirectHandoff) {
            discardDirectHandoff(
              "Your recommendation link expired. Please continue with your contact details.",
            );
            return null;
          }

          const refreshedIntake = await refreshBookingContext();

          if (!refreshedIntake) {
            setServices([]);
            setServicesLoadedToken(null);
            handleBookingContextRecoveryFailure(
              "Please confirm your contact details to refresh your booking options.",
            );
            return null;
          }

          if (!refreshedIntake.bookingEnabled) {
            setServices([]);
            setServicesLoadedToken(null);
            disableBookingFlow();
            return null;
          }

          try {
            const refreshedServices = await getPublicServices(
              slug,
              refreshedIntake.bookingContextToken,
            );
            applyServices(refreshedServices, refreshedIntake);
            return refreshedServices;
          } catch (retryError) {
            if (isBookingDisabledError(retryError)) {
              setServices([]);
              setServicesLoadedToken(null);
              disableBookingFlow();
              return null;
            }

            const retryMessage =
              retryError instanceof Error
                ? retryError.message
                : "Unable to load services for online booking.";

            setServices([]);
            setServicesLoadedToken(null);
            setServiceError(retryMessage);
            return null;
          }
        }

        const message =
          error instanceof Error
            ? error.message
            : "Unable to load services for online booking.";

        setServices([]);
        setServicesLoadedToken(null);
        setServiceError(message);
        return null;
      } finally {
        setServicesLoading(false);
      }
    },
    [
      clearAvailabilityState,
      disableBookingFlow,
      discardDirectHandoff,
      handleBookingContextRecoveryFailure,
      isDirectHandoff,
      refreshBookingContext,
      slug,
    ],
  );

  const handleSelectedServiceUnavailable = useCallback(
    async (intakeOverride?: PublicBookingIntakeData | null) => {
      const activeIntake =
        intakeOverride ??
        (intakeState.status === "ready" ? intakeState.data : null);

      setSelectedServices([]);
      clearAvailabilityState();
      setCurrentStep(2);
      setConfirmError(null);

      if (activeIntake?.bookingContextToken) {
        await loadServicesForIntake(activeIntake);
      } else {
        setServices([]);
        setServicesLoadedToken(null);
      }

      setServiceError(
        "Selected service is not available. Please choose another service.",
      );
    },
    [clearAvailabilityState, intakeState, loadServicesForIntake],
  );

  const getAvailabilityForCurrentContext = useCallback(
    async ({
      allowTokenRefresh = true,
      signal,
    }: { allowTokenRefresh?: boolean; signal?: AbortSignal } = {}) => {
      const activeIntake = intakeState.status === "ready" ? intakeState.data : null;

      if (!activeIntake?.bookingContextToken) {
        return null;
      }

      try {
        return await getPublicAvailability(slug, activeIntake.bookingContextToken, {
          signal,
        });
      } catch (error) {
        if (isBookingDisabledError(error)) {
          disableBookingFlow();
          return null;
        }

        if (allowTokenRefresh && isBookingContextExpiredError(error)) {
          const refreshedIntake = await refreshBookingContext();

          if (!refreshedIntake) {
            handleBookingContextRecoveryFailure(
              "Please confirm your contact details to refresh availability.",
            );
            return null;
          }

          if (!refreshedIntake.bookingEnabled) {
            disableBookingFlow();
            return null;
          }

          const refreshedServices = await loadServicesForIntake(refreshedIntake, {
            allowTokenRefresh: false,
          });

          if (!refreshedServices || !selectedServicesRef.current.length) {
            handleBookingContextRecoveryFailure(
              "Your available services changed. Please select a service again.",
            );
            return null;
          }

          return getPublicAvailability(slug, refreshedIntake.bookingContextToken, {
            signal,
          });
        }

        throw error;
      }
    },
    [
      disableBookingFlow,
      handleBookingContextRecoveryFailure,
      intakeState,
      loadServicesForIntake,
      refreshBookingContext,
      slug,
    ],
  );

  const getSlotsForDate = useCallback(
    async (
      date: string,
      {
        allowTokenRefresh = true,
        forceRefresh = false,
        signal,
      }: {
        allowTokenRefresh?: boolean;
        forceRefresh?: boolean;
        signal?: AbortSignal;
      } = {},
    ) => {
      const activeIntake = intakeState.status === "ready" ? intakeState.data : null;
      const activeSelectedServiceIds = selectedServicesRef.current.map(
        (service) => service.id,
      );

      if (!activeIntake?.bookingContextToken || !activeSelectedServiceIds.length) {
        return null;
      }

      const cacheKey = getSlotCacheKey({
        bookingContextToken: activeIntake.bookingContextToken,
        date,
        serviceIds: activeSelectedServiceIds,
      });

      if (forceRefresh) {
        slotResponseCacheRef.current.delete(cacheKey);
        slotRequestCacheRef.current.delete(cacheKey);
      } else {
        const cachedResponse = slotResponseCacheRef.current.get(cacheKey);
        if (cachedResponse) {
          return cachedResponse;
        }

        const inFlightRequest = slotRequestCacheRef.current.get(cacheKey);
        if (inFlightRequest) {
          return inFlightRequest;
        }
      }

      const requestPromise = (async () => {
        try {
          // Slots are always requested with every selected service id so the
          // backend can calculate the combined appointment duration.
          return await getPublicSlots(
            slug,
            activeSelectedServiceIds,
            date,
            activeIntake.bookingContextToken,
            { signal },
          );
        } catch (error) {
          if (isBookingDisabledError(error)) {
            disableBookingFlow();
            return null;
          }

          if (isSelectedServiceUnavailableError(error)) {
            if (isDirectHandoff) {
              discardDirectHandoff(
                "That recommended service is no longer available. Please choose another service.",
              );
              return null;
            }

            await handleSelectedServiceUnavailable(activeIntake);
            return null;
          }

          if (allowTokenRefresh && isBookingContextExpiredError(error)) {
            if (isDirectHandoff) {
              discardDirectHandoff(
                "Your recommendation link expired. Please continue with your contact details.",
              );
              return null;
            }

            const refreshedIntake = await refreshBookingContext();

            if (!refreshedIntake) {
              handleBookingContextRecoveryFailure(
                "Please confirm your contact details to refresh availability.",
              );
              return null;
            }

            if (!refreshedIntake.bookingEnabled) {
              disableBookingFlow();
              return null;
            }

            const refreshedServices = await loadServicesForIntake(refreshedIntake, {
              allowTokenRefresh: false,
            });

            if (!refreshedServices || !selectedServicesRef.current.length) {
              handleBookingContextRecoveryFailure(
                "Your available services changed. Please select a service again.",
              );
              return null;
            }

            try {
              return await getPublicSlots(
                slug,
                selectedServicesRef.current.map((service) => service.id),
                date,
                refreshedIntake.bookingContextToken,
                { signal },
              );
            } catch (retryError) {
              if (isBookingDisabledError(retryError)) {
                disableBookingFlow();
                return null;
              }

              if (isSelectedServiceUnavailableError(retryError)) {
                await handleSelectedServiceUnavailable(refreshedIntake);
                return null;
              }

              throw retryError;
            }
          }

          throw error;
        }
      })();

      slotRequestCacheRef.current.set(cacheKey, requestPromise);

      try {
        const response = await requestPromise;
        const requestIsStillCurrent =
          slotRequestCacheRef.current.get(cacheKey) === requestPromise;

        if (response && requestIsStillCurrent) {
          slotResponseCacheRef.current.set(cacheKey, response);
        }

        return response;
      } finally {
        if (slotRequestCacheRef.current.get(cacheKey) === requestPromise) {
          slotRequestCacheRef.current.delete(cacheKey);
        }
      }
    },
    [
      disableBookingFlow,
      discardDirectHandoff,
      handleBookingContextRecoveryFailure,
      handleSelectedServiceUnavailable,
      intakeState,
      isDirectHandoff,
      loadServicesForIntake,
      refreshBookingContext,
      slug,
    ],
  );

  useEffect(() => {
    let cancelled = false;
    const abortController = new AbortController();

    async function loadAvailability() {
      // Initial availability load picks the first future date with actual slots,
      // falling back to generated date options so users can still inspect dates.
      if (
        !selectedServiceIds.length ||
        bookingDisabled ||
        !bookingContextToken ||
        !servicesAreSynced
      ) {
        setSlotPreviews({});
        return;
      }

      setAvailabilityLoading(true);
      setSlotsError(null);

      try {
        const availability = await getAvailabilityForCurrentContext({
          signal: abortController.signal,
        });
        if (cancelled) {
          return;
        }

        if (!availability) {
          return;
        }

        const dates = extractAvailabilityDates(availability);
        const recurringDates = buildAvailabilityDateOptions(
          extractAvailabilityRows(availability),
        );
        const fallbackDates = buildFallbackDateOptions();
        const nextDates = Array.from(
          new Set(
            dates.length
              ? dates
              : recurringDates.length
                ? recurringDates
                : fallbackDates,
          ),
        );

        const today = getTodayDateValue();
        const suggestedDates = initialSuggestedDatesRef.current.filter(
          (date) => date >= today,
        );
        const candidateDates = Array.from(new Set([...suggestedDates, ...nextDates]));
        let nextTimezone =
          extractAvailabilityTimezone(availability) ?? stylist.timezone ?? null;
        let nextSelectedDate = candidateDates[0] ?? "";
        let nextSlots: PublicSlot[] = [];

        for (const date of candidateDates) {
          const response = await getSlotsForDate(date, {
            signal: abortController.signal,
          });
          if (cancelled) {
            return;
          }

          if (!response) {
            return;
          }

          nextTimezone = response.timezone ?? nextTimezone;

          const responseSlots = getBookableSlots(response);

          if (responseSlots.length > 0) {
            nextSelectedDate = date;
            nextSlots = responseSlots;
            break;
          }
        }

        setAvailabilityTimezone(nextTimezone);
        setDateOptions(candidateDates);
        setSelectedDate(nextSelectedDate);
        setSlotPreviews(nextSlots.length ? { [nextSelectedDate]: nextSlots } : {});
        setSlots(nextSlots);
        setLoadedSlotsDate(nextSelectedDate);
      } catch (error) {
        if (cancelled) {
          return;
        }

        const fallbackDates = buildFallbackDateOptions();
        setDateOptions(fallbackDates);
        setSelectedDate((currentDate) => currentDate || fallbackDates[0] || "");
        setSlotPreviews({});
        setSlots([]);
        setLoadedSlotsDate("");
        setSelectedSlot(null);
        setSlotsError(
          error instanceof Error
            ? error.message
            : "Unable to load availability right now.",
        );
      } finally {
        if (!cancelled) {
          setAvailabilityLoading(false);
        }
      }
    }

    void loadAvailability();

    return () => {
      cancelled = true;
      abortController.abort();
    };
  }, [
    bookingContextToken,
    bookingDisabled,
    getAvailabilityForCurrentContext,
    getSlotsForDate,
    selectedServiceIds,
    servicesAreSynced,
    stylist.timezone,
  ]);

  useEffect(() => {
    let cancelled = false;
    const abortController = new AbortController();

    async function loadSlots() {
      if (
        !selectedServiceIds.length ||
        !selectedDate ||
        bookingDisabled ||
        !bookingContextToken ||
        !servicesAreSynced
      ) {
        return;
      }

      setSlotsError(null);

      try {
        const response = await getSlotsForDate(selectedDate, {
          signal: abortController.signal,
        });
        if (cancelled) {
          return;
        }

        if (!response) {
          return;
        }

        const nextSlots = filterRejectedSlots(
          getBookableSlots(response),
          rejectedSlotStarts,
        );

        setAvailabilityTimezone(response.timezone ?? activeTimezone);
        setSlots(nextSlots);
        setLoadedSlotsDate(selectedDate);
        setSlotPreviews((currentPreviews) => ({
          ...currentPreviews,
          [selectedDate]: nextSlots,
        }));
        setSelectedSlot((currentSlot) =>
          nextSlots.find((slot) => slot.start === currentSlot?.start) ?? null,
        );
      } catch (error) {
        if (cancelled) {
          return;
        }

        setSlots([]);
        setLoadedSlotsDate("");
        setSelectedSlot(null);
        setSlotsError(
          error instanceof Error
            ? error.message
            : "Unable to load time slots for this date.",
        );
      }
    }

    void loadSlots();

    return () => {
      cancelled = true;
      abortController.abort();
    };
  }, [
    activeTimezone,
    bookingContextToken,
    bookingDisabled,
    getSlotsForDate,
    rejectedSlotStarts,
    selectedDate,
    selectedServiceIds,
    servicesAreSynced,
  ]);

  useEffect(() => {
    let cancelled = false;
    const abortController = new AbortController();

    async function loadSlotPreviews() {
      // Previewing multiple days is intentionally capped so the first time-step
      // render does not fan out into weeks of parallel slot requests.
      if (
        !selectedServiceIds.length ||
        !dateOptions.length ||
        bookingDisabled ||
        !bookingContextToken ||
        !servicesAreSynced
      ) {
        setSlotPreviews({});
        return;
      }

      const today = getTodayDateValue();
      const previewDates = Array.from(
        new Set(dateOptions.filter((date) => date >= today)),
      ).slice(0, 10);

      if (!previewDates.length) {
        setSlotPreviews({});
        return;
      }

      const previewEntries = await Promise.all(
        previewDates.map(async (date) => {
          try {
            const response = await getSlotsForDate(date, {
              allowTokenRefresh: false,
              signal: abortController.signal,
            });

            return [date, response ? getBookableSlots(response) : []] as const;
          } catch {
            return [date, [] as PublicSlot[]] as const;
          }
        }),
      );

      if (cancelled) {
        return;
      }

      setSlotPreviews((currentPreviews) => ({
        ...currentPreviews,
        ...Object.fromEntries(previewEntries),
      }));
    }

    void loadSlotPreviews();

    return () => {
      cancelled = true;
      abortController.abort();
    };
  }, [
    bookingContextToken,
    bookingDisabled,
    dateOptions,
    getSlotsForDate,
    selectedServiceIds,
    servicesAreSynced,
  ]);

  async function handleContinueFromDetails() {
    if (!validateDetails()) {
      return;
    }

    if (servicesLoading) {
      return;
    }

    let nextIntake = intakeState.status === "ready" ? intakeState.data : null;

    if (!nextIntake) {
      nextIntake = await runIntake();

      if (!nextIntake) {
        return;
      }
    }

    if (!nextIntake.bookingEnabled) {
      disableBookingFlow();
      return;
    }

    if (!servicesAreSynced || servicesLoadedToken !== nextIntake.bookingContextToken) {
      const loadedServices = await loadServicesForIntake(nextIntake);

      if (!loadedServices) {
        return;
      }

      setCurrentStep(2);
      return;
    }

    if (!sortedServices.length) {
      setServiceError("No services are currently available for online booking.");
      return;
    }

    setServiceError(null);
    setCurrentStep(2);
  }

  function handleContinueFromServices() {
    if (!selectedServices.length) {
      setServiceError("Please select at least one service to continue.");
      return;
    }

    setServiceError(null);
    setCurrentStep(3);
  }

  async function handleContinueFromTime() {
    if (!selectedSlot) {
      setSlotsError("Please select a time to continue.");
      return;
    }

    const verifiedSlot = await revalidateSelectedSlot();

    if (!verifiedSlot) {
      return;
    }

    setSlotsError(null);
    setCurrentStep(4);
  }

  async function refreshSlotsForSelectedDate({
    clearSelection = true,
    rejectedSlotStart,
  }: {
    clearSelection?: boolean;
    rejectedSlotStart?: string;
  } = {}) {
    if (!selectedServiceIds.length || !selectedDate) {
      return null;
    }

    try {
      const response = await getSlotsForDate(selectedDate, {
        forceRefresh: true,
      });

      if (!response) {
        return null;
      }

      const rawSlots = getBookableSlots(response);
      const startsToExclude = rejectedSlotStart
        ? [...rejectedSlotStarts, rejectedSlotStart]
        : rejectedSlotStarts;
      const nextSlots = filterRejectedSlots(rawSlots, startsToExclude);

      setSlots(nextSlots);
      setLoadedSlotsDate(selectedDate);
      setSlotPreviews((currentPreviews) => ({
        ...currentPreviews,
        [selectedDate]: nextSlots,
      }));
      if (clearSelection) {
        setSelectedSlot(null);
      }
      setAvailabilityTimezone(response.timezone ?? activeTimezone);
      return {
        rawSlots,
        slots: nextSlots,
      };
    } catch {
      setSlots([]);
      setLoadedSlotsDate("");
      if (clearSelection) {
        setSelectedSlot(null);
      }
      return null;
    }
  }

  async function revalidateSelectedSlot() {
    if (!selectedSlot) {
      setSlotsError("Please select a time to continue.");
      return null;
    }

    setAvailabilityLoading(true);
    setSlotsError(null);

    try {
      const refreshedSlots = await refreshSlotsForSelectedDate({
        clearSelection: false,
      });
      const verifiedSlot =
        refreshedSlots?.slots.find((slot) => slot.start === selectedSlot.start) ??
        null;

      if (!verifiedSlot) {
        setSelectedSlot(null);
        setSlotsError("That time just became unavailable. Please choose another time.");
        setConfirmError(null);
        setCurrentStep(3);
        return null;
      }

      setSelectedSlot(verifiedSlot);
      return verifiedSlot;
    } finally {
      setAvailabilityLoading(false);
    }
  }

  async function handleSubmitBooking() {
    if (submittingRef.current) {
      return;
    }

    if (!primarySelectedService || !selectedSlot || !bookingContextToken) {
      return;
    }

    submittingRef.current = true;
    setSubmitting(true);
    setConfirmError(null);

    try {
      const idempotencyKey = createBookingIdempotencyKey();
      const verifiedSlot = await revalidateSelectedSlot();

      if (!verifiedSlot) {
        return;
      }

      const bookingRequestBase = {
        stylist_slug: slug,
        service_id: primarySelectedService.id,
        requested_datetime: verifiedSlot.start,
        referral_code: referralCodeRef.current || undefined,
        booking_attribution_token: getUsableBookingAttributionToken(
          bookingAttribution,
          slug,
        ),
        sms_opt_in: smsOptIn,
        notes: buildBookingNotes(selectedServices, notes),
      };
      const bookingRequest: CreatePublicBookingBody = isDirectHandoff
        ? {
            ...bookingRequestBase,
            booking_context_token: bookingContextToken,
          }
        : {
            ...bookingRequestBase,
            guest_first_name: parsedName.firstName,
            guest_last_name: parsedName.lastName,
            guest_email: email.trim(),
            guest_phone: phone.trim(),
            booking_context_token: bookingContextToken,
            booking_inquiry_token: bookingInquiryToken ?? undefined,
          };
      const response = await createPublicBooking(bookingRequest, { idempotencyKey });

      clearStoredReferralCode(slug);
      referralCodeRef.current = null;
      setReferralCode(null);
      setConfirmation(response);
      setCurrentStep(5);
    } catch (error) {
      const apiReason = getApiErrorReason(error);
      const message =
        apiReason ??
        (error instanceof Error
          ? error.message
          : "Unable to submit your booking right now.");

      const debugPayload = {
        // Keep browser diagnostics to structured, non-customer identifiers.
        // Backend messages and reasons can include untrusted capability values.
        status: error instanceof ApiError ? error.status : undefined,
        code: error instanceof ApiError ? error.code : undefined,
        requested_datetime: selectedSlot.start,
        service_id: primarySelectedService.id,
        stylist_slug: slug,
      };

      console.error(`Booking submit failed ${JSON.stringify(debugPayload)}`);

      const attributionErrorCode = getBookingAttributionErrorCode(error);

      if (attributionErrorCode) {
        // These API codes are returned before appointment creation. Clear the
        // rejected opaque context and leave the customer on confirmation so a
        // deliberate retry submits the unchanged booking without attribution.
        clearBookingAttribution();
        setConfirmError(
          "We couldn't apply that booking link. Please try booking again.",
        );
      } else if (
        isDirectHandoff
        && (
          isBookingIdentityRequiredError(error)
          || isBookingContextExpiredError(error)
          || (error instanceof ApiError && error.code === "booking_inquiry_handoff_unavailable")
        )
      ) {
        discardDirectHandoff(
          "Please confirm your contact details before finishing this booking.",
        );
      } else if (isSlotConflictError(error, message)) {
        const rejectedSlotStart = selectedSlot.start;

        setRejectedSlotStarts((currentStarts) =>
          currentStarts.includes(rejectedSlotStart)
            ? currentStarts
            : [...currentStarts, rejectedSlotStart],
        );
        const refreshedSlots = await refreshSlotsForSelectedDate({
          rejectedSlotStart,
        });
        const slotStillReturnedByAvailabilityEndpoint = Boolean(
          refreshedSlots?.rawSlots.some(
            (slot) => slot.start === rejectedSlotStart,
          ),
        );

        console.error(
          `Booking conflict refresh diagnostics ${JSON.stringify({
            requested_datetime: rejectedSlotStart,
            service_id: primarySelectedService.id,
            stylist_slug: slug,
            slotStillReturnedByAvailabilityEndpoint,
            refreshedSlotCount: refreshedSlots?.slots.length ?? null,
            rawRefreshedSlotCount: refreshedSlots?.rawSlots.length ?? null,
          })}`,
        );
        setSlotsError("That time just became unavailable. Please choose another time.");
        setConfirmError(null);
        setCurrentStep(3);
      } else if (isBookingSchemaMismatch(error)) {
        setConfirmError(buildBookingServiceUnavailableMessage(stylist));
      } else if (isBookingDisabledError(error)) {
        disableBookingFlow();
      } else {
        setConfirmError(message);
      }
    } finally {
      submittingRef.current = false;
      setSubmitting(false);
    }
  }

  function handleReset() {
    // A completed booking must return to a genuinely fresh flow rather than
    // leaving the completed customer's choices ready to submit again.
    initialServiceIdsRef.current = [];
    initialSuggestedDatesRef.current = [];
    initialServicePrefillAttemptedRef.current = true;
    setHandoffState({ status: "idle" });
    invalidateBookingContext();
    resetDetails();
    setNotes("");
    setSmsOptIn(false);
    setConfirmError(null);
    setConfirmation(null);
    clearReferencePhotoSelection();
  }

  function handleReferencePhotoSelect(file: File) {
    setReferencePhotoFile(file);
    setReferencePhotoPreviewUrl((currentUrl) => {
      if (currentUrl) {
        URL.revokeObjectURL(currentUrl);
      }

      return URL.createObjectURL(file);
    });
  }

  function clearReferencePhotoSelection() {
    setReferencePhotoFile(null);
    setReferencePhotoPreviewUrl((currentUrl) => {
      if (currentUrl) {
        URL.revokeObjectURL(currentUrl);
      }

      return null;
    });
  }

  function handleToggleService(service: PublicService) {
    setSelectedServices((currentServices) => {
      const alreadySelected = currentServices.some(
        (currentService) => currentService.id === service.id,
      );

      if (alreadySelected) {
        return currentServices.filter(
          (currentService) => currentService.id !== service.id,
        );
      }

      return [service];
    });
    clearAvailabilityState();
    setConfirmError(null);
    setServiceError(null);
  }

  if (confirmation && selectedServices.length && selectedSlot) {
    return (
      <div className="mx-auto max-w-[620px] bg-transparent p-6 sm:rounded-[30px] sm:border sm:border-white/80 sm:bg-card sm:p-8 sm:shadow-[0_24px_80px_rgba(17,24,39,0.08)]">
        <BookedStep
          confirmation={confirmation}
          stylist={stylist}
          services={selectedServices}
          slot={selectedSlot}
          initialReferencePhotoFile={referencePhotoFile}
          onInitialReferencePhotoConsumed={() => setReferencePhotoFile(null)}
          onDone={handleReset}
        />
      </div>
    );
  }

  if (handoffState.status === "loading") {
    return (
      <div className="mx-auto max-w-[620px] rounded-[30px] border border-white/80 bg-card p-8 text-center shadow-[0_24px_80px_rgba(17,24,39,0.08)]">
        <h2 className="text-2xl font-semibold tracking-tight text-foreground">
          Preparing your recommendation
        </h2>
        <p className="mt-3 text-sm leading-6 text-muted">
          Loading the service and available appointment times…
        </p>
      </div>
    );
  }

  return (
    <div
      className={[
        "bg-transparent p-6 sm:rounded-[30px] sm:border sm:border-white/80 sm:bg-card sm:p-8 sm:shadow-[0_24px_80px_rgba(17,24,39,0.08)]",
        currentStep === 3 ? "mx-auto max-w-[430px]" : "lg:grid lg:grid-cols-[300px_minmax(0,1fr)] lg:gap-8",
      ].join(" ")}
    >
      {currentStep !== 3 ? <PublicBookingProfile stylist={stylist} /> : null}

      <div className="lg:min-w-0">
        {bookingDisabled ? (
        <div className="mt-8 rounded-3xl border border-border bg-zinc-50 p-6 lg:mt-0">
          <h2 className="text-2xl font-semibold tracking-tight text-foreground">
            {pageName}
          </h2>
          <p className="mt-3 text-sm leading-6 text-muted">
            Online booking is currently unavailable.
          </p>
          {stylist.phone_number ? (
            <p className="mt-4 text-sm font-medium text-foreground">
              Contact: {stylist.phone_number}
            </p>
          ) : null}
        </div>
        ) : (
        <>
          {currentStep !== 3 ? (
            <div className="mt-8 lg:mt-0">
              <BookingStepper currentStep={currentStep} />
            </div>
          ) : null}

          {currentStep === 1 ? (
            <DetailsStep
              intro={stylist.intro}
              introDescription={stylist.intro_description}
              values={{ fullName, email, phone }}
              errors={detailsErrors}
              services={sortedServices}
              intake={intakeData}
              intakeLoading={intakeState.status === "loading"}
              servicesLoading={servicesLoading || intakeRefreshing}
              selectedServices={selectedServices}
              serviceError={serviceError}
              canBeginServiceSelection={canBeginServiceSelection}
              showServicePicker={false}
              recommendedServiceId={intakeData?.recommendedService?.serviceId ?? null}
              onChange={handleDetailsChange}
              onToggleService={handleToggleService}
                onContinue={handleContinueFromDetails}
                inquiryCallout={<BookingInquiryCard
                  slug={slug}
                  config={stylist.booking_request_form}
                  enabled={stylist.booking_request_form_enabled === true}
                  contact={{
                    firstName: intakeData?.submittedContact.firstName ?? parsedName.firstName,
                    lastName: intakeData?.submittedContact.lastName ?? parsedName.lastName,
                    phone: intakeData?.submittedContact.phoneNormalized ?? phone,
                    email: intakeData?.submittedContact.email ?? email,
                  }}
                  validateContact={validateDetails}
                  variant="details"
                />}
            />
          ) : null}

          {currentStep === 2 ? (
            <DetailsStep
              mode="services"
              values={{ fullName, email, phone }}
              errors={detailsErrors}
              services={sortedServices}
              intake={intakeData}
              intakeLoading={intakeState.status === "loading"}
              servicesLoading={servicesLoading || intakeRefreshing}
              selectedServices={selectedServices}
              serviceError={serviceError}
              canBeginServiceSelection={canBeginServiceSelection}
              showServicePicker
              recommendedServiceId={intakeData?.recommendedService?.serviceId ?? null}
              onChange={handleDetailsChange}
              onToggleService={handleToggleService}
              onBack={() => setCurrentStep(1)}
              onContinue={handleContinueFromServices}
                inquiryCallout={<BookingInquiryCard
                slug={slug}
                config={stylist.booking_request_form}
                enabled={stylist.booking_request_form_enabled === true}
                contact={{
                  firstName: intakeData?.submittedContact.firstName ?? parsedName.firstName,
                  lastName: intakeData?.submittedContact.lastName ?? parsedName.lastName,
                  phone: intakeData?.submittedContact.phoneNormalized ?? phone,
                  email: intakeData?.submittedContact.email ?? email,
                }}
                  validateContact={validateDetails}
                  variant="services"
              />}
            />
          ) : null}

          {currentStep === 3 ? (
            <TimeStep
              selectedDate={selectedDate}
              selectedSlot={selectedSlot}
              upcomingDays={upcomingAvailabilityDays}
              loading={availabilityLoading}
              error={slotsError}
              timezone={activeTimezone}
              waitlistCta={
                shouldShowWaitlistCta ? (
                  <WaitlistCallout
                    slug={slug}
                    selectedDate={selectedDate}
                    selectedServiceId={primarySelectedService?.id ?? null}
                    selectedService={primarySelectedService}
                    defaultClientName={fullName}
                    defaultClientEmail={email}
                    defaultClientPhone={phone}
                  />
                ) : null
              }
              onDateSelect={(date) => {
                setSelectedDate(date);
                setSelectedSlot(null);
                setSlotsError(null);
              }}
              onSlotSelect={(slot) => {
                setSelectedSlot(slot);
                setSlotsError(null);
                setConfirmError(null);
              }}
              onBack={() => {
                if (isDirectHandoff) {
                  discardDirectHandoff();
                } else {
                  setCurrentStep(2);
                }
              }}
              onContinue={handleContinueFromTime}
            />
          ) : null}

          {currentStep === 4 && selectedServices.length && selectedSlot ? (
            <ConfirmStep
              stylist={stylist}
              services={selectedServices}
              slot={selectedSlot}
              fullName={activeHandoff?.customer.display_name ?? fullName.trim()}
              email={activeHandoff?.customer.email_masked ?? email.trim()}
              phone={activeHandoff?.customer.phone_masked ?? phone.trim()}
              notes={notes}
              smsOptIn={smsOptIn}
              referencePhotoFile={referencePhotoFile}
              referencePhotoPreviewUrl={referencePhotoPreviewUrl}
              submitting={submitting}
              error={confirmError}
              timezone={activeTimezone}
              onNotesChange={setNotes}
              onSmsOptInChange={setSmsOptIn}
              onReferencePhotoSelect={handleReferencePhotoSelect}
              onReferencePhotoRemove={clearReferencePhotoSelection}
              onEdit={(step) => {
                if (isDirectHandoff && (step === 1 || step === 2)) {
                  discardDirectHandoff();
                } else {
                  setCurrentStep(step);
                }
              }}
              onSubmit={handleSubmitBooking}
            />
          ) : null}

          <div className="mt-6 text-xs font-medium text-muted">
            {canShowTimeStep ? formatTimezoneLabel(activeTimezone) : null}
          </div>
        </>
        )}
      </div>
    </div>
  );
}
